css:
.container {
  width: 100%;
  height: 100%;
  /* Add your background pattern here */
  background: linear-gradient(#000 2px, transparent 2px),
    linear-gradient(90deg, #000 2px, transparent 2px);
  background-size: 100px 100px;
}
.container::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: linear-gradient(-45deg, #000 20px, transparent 20px),
    linear-gradient(-135deg, #000 20px, transparent 20px),
    linear-gradient(135deg, #000 20px, transparent 20px),
    linear-gradient(45deg, #000 20px, transparent 20px);
  background-size: 100px 100px;
  background-position: 50px 50px;
}

.container::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: linear-gradient(45deg, #000 20px, transparent 20px),
    linear-gradient(-45deg, #000 20px, transparent 20px),
    linear-gradient(135deg, #000 20px, transparent 20px),
    linear-gradient(-135deg, #000 20px, transparent 20px);
  background-size: 100px 100px;
  background-position: 1px 1px;
}
